int process_escape_sequence(FILE *input, char word[], int *word_index, int *escape_active) {
    int c;
    int value = 0;
    int base = 10;

    if (*escape_active) {
        if (word[*word_index] == '\n') {
            (void)fgetc(input);
            return 0;
        }

        if (word[*word_index] == 'a') {
            value = '\a';
        } else if (word[*word_index] == 'b') {
            value = '\b';
        } else if (word[*word_index] == 'f') {
            value = '\f';
        } else if (word[*word_index] == 'n') {
            value = '\n';
        } else if (word[*word_index] == 'r') {
            value = '\r';
        } else if (word[*word_index] == 't') {
            value = '\t';
        } else if (word[*word_index] == 'v') {
            value = '\v';
        } else if (word[*word_index] == '0' || word[*word_index] == '1' ||
                   word[*word_index] == '2' || word[*word_index] == '3') {
            base = 8;
            value = word[(*word_index)++] - '0';
        } else if (word[*word_index] == 'x') {
            base = 16;
            (*word_index)++;
        } else {
            (*escape_active) = 0;
            return 0;
        }

        if (base == 8 || base == 16) {
            int digits_read = 0;

            while (digits_read < (base == 8 ? 3 : 2)) {
                c = fgetc(input);
                if ((base == 8 && !isdigit(c)) || (base == 16 && !isxdigit(c))) {
                    ungetc(c, input);
                    break;
                }

                if (isdigit(c)) {
                    value = value * base + (c - '0');
                } else {
                    value = value * base + (tolower(c) - 'a' + 10);
                }
                digits_read++;
            }

            if (digits_read == 0) {
                (*escape_active) = 0;
                return 0;
            }
        }

        if (*word_index < MAX_WORD_LENGTH) {
            word[(*word_index)++] = value;
        }
        (*escape_active) = 0;
        return 1;
    }

    c = fgetc(input);
    if (c == EOF) {
        return -1;
    }

    if (c == '\\') {
        *escape_active = 1;
        return 0;
    }

    if (*word_index < MAX_WORD_LENGTH) {
        word[(*word_index)++] = c;
    }
    return 0;
}

